+	environmentId: string;
+	/** Null when `cwd` is not inside a git repository. */
+	root: string | null;
+	branch: string | null;
+	hasUpstream: boolean;
+	ahead: number;
+	behind: number;
+	staged: SourceControlFile[];
+	unstaged: SourceControlFile[];
+	untracked: SourceControlFile[];
+	commits: SourceControlCommit[];
+};
